      const params=new URLSearchParams(location.search),jobId=params.get('job')||'ai-product',job=jobs[jobId]||jobs['ai-product'],detailUrl=`/agent/job-detail?id=${encodeURIComponent(jobId)}`,storageKey=`zhipin-ai-job-chat-${jobId}`;
      const byId=id=>document.getElementById(id),messages=byId('messages'),input=byId('questionInput'),send=byId('sendButton');let history=[],replyTimer;
      byId('backLink').href=detailUrl;byId('mobileBackLink').href=detailUrl;byId('detailLink').href=detailUrl;byId('jobTitle').textContent=job.title;byId('company').textContent=job.company;byId('salary').textContent=job.salary;byId('meta').textContent=job.meta;byId('matchScore').textContent=job.score+'%';byId('matchBar').style.width=job.score+'%';byId('headContext').textContent=job.title;byId('focusList').innerHTML=job.focus.map(item=>`<li>${item}</li>`).join('');document.title=job.title+' · AI 求职助手';
