      try{history=JSON.parse(localStorage.getItem(storageKey)||'[]')}catch(error){history=[]}
      if(!history.length)history=[{role:'assistant',text:initialMessage,time:'刚刚'}];
      function escapeText(value){const node=document.createElement('span');node.textContent=value;return node.innerHTML}
      function renderMessage(item){const row=document.createElement('div');row.className='message '+(item.role==='user'?'user':'assistant');row.innerHTML=`<span class="bubble-avatar">${item.role==='user'?'林':'AI'}</span><div class="bubble-wrap"><div class="bubble">${escapeText(item.text)}</div><div class="bubble-time">${escapeText(item.time||'刚刚')}</div></div>`;messages.appendChild(row)}
      function renderHistory(){messages.querySelectorAll('.message').forEach(node=>node.remove());history.forEach(renderMessage);messages.scrollTop=messages.scrollHeight}function saveHistory(){try{localStorage.setItem(storageKey,JSON.stringify(history.slice(-30)))}catch(error){}}
      function answerFor(question){if(/匹配|优势|适合/.test(question))return `你的综合匹配度为 ${job.score}%。优势主要集中在${job.focus[0]}和${job.focus[1]}。建议在简历中用一个量化项目结果证明相关能力。`;if(/面试|问题|准备/.test(question))return `这类岗位通常会重点追问三部分：${job.focus.join('、')}。准备时可各整理一个 STAR 案例，并补充你的具体决策和结果数据。`;if(/简历|优化/.test(question))return `投递「${job.title}」前，建议把最相关的项目提前，并在项目首句明确职责、业务目标和量化结果。关键词可自然覆盖：${job.focus.slice(0,2).join('、')}。`;if(/流程|多久|时间/.test(question))return `该岗位当前参考流程为简历初筛、AI 面试、HR 复试和 Offer 沟通。初筛通常需要 1-3 天，后续时间由企业与求职者共同确认。`;if(/薪资|待遇/.test(question))return `页面显示的岗位薪资为 ${job.salary}。实际定薪通常结合相关经验、面试表现和职级评估，建议在 HR 沟通阶段确认薪资结构。`;return `针对「${job.title}」，我建议先围绕${job.focus[0]}梳理你的相关经历。你也可以继续问我匹配优势、简历优化、面试重点或投递流程。`}
