      renderHistory();input.addEventListener('input',()=>send.disabled=!input.value.trim());byId('composer').addEventListener('submit',event=>{event.preventDefault();ask(input.value)});document.querySelectorAll('.suggestion').forEach(button=>button.addEventListener('click',()=>ask(button.textContent)));
})
